css:
.container {
  width: 100%;
  height: 100%;
  background-image: repeating-linear-gradient(
      90deg,
      #111111 1%,
      transparent 1% 2%,
      #111111 2% 3%
    ),
    repeating-linear-gradient(
      0deg,
      #111111 1%,
      transparent 1% 2%,
      #111111 2% 3%
    ),
    repeating-radial-gradient(
      ellipse at 0% 0%,
      white 10%,
      transparent 10% 20%,
      white 20% 30%
    ),
    repeating-radial-gradient(
      ellipse at 100% 100%,
      white 10%,
      transparent 10% 20%,
      white 20% 30%
    );
  background-color: gray;
}
